import { execFileSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import * as errore from "errore";

class SemvariantError extends errore.createTaggedError({
  name: "SemvariantError",
  message: "$detail",
}) {}

type Rule = {
  ruleId: string;
  title: string;
  guides: readonly string[];
  content: string;
};

type GuideDrift = {
  missing: string[];
  changed: string[];
  stale: string[];
  collisions: string[];
};

const rulesDirectory = "tools/semvariant/rules";
const generatedMarker =
  "<!-- GENERATED BY pnpm semvariant generate. DO NOT EDIT. -->";
const excludedDirectories = new Set([".git", "node_modules", "data"]);
const usage = `Usage:
  pnpm semvariant show <ID> [ID...]
  pnpm semvariant search <query> [query...]
  pnpm semvariant context <path> [...] [--full]
  pnpm semvariant context --staged [--full]
  pnpm semvariant context --diff <rev> [--full]
  pnpm semvariant generate
  pnpm semvariant check
  pnpm semvariant help`;

function filesystem<T>(detail: string, operation: () => T) {
  return errore.try({
    try: operation,
    catch: (cause) => new SemvariantError({ detail, cause }),
  });
}

function inspect(target: string) {
  return filesystem(`Cannot inspect ${target}`, () =>
    fs.lstatSync(target, { throwIfNoEntry: false }),
  );
}

function read(target: string) {
  return filesystem(`Cannot read ${target}`, () =>
    fs.readFileSync(target, "utf8"),
  );
}

function parseGuides(frontmatter: string) {
  const guides: string[] = [];
  let found = false;
  let block = false;
  for (const line of frontmatter.split(/\r?\n/)) {
    const item = line.match(/^\s+-\s+(.+?)\s*$/);
    if (item && block) {
      const value = parseDirectory(item[1]!);
      if (value instanceof Error) return value;
      guides.push(value);
      continue;
    }
    const field = line.match(/^guides:(?:\s*(.*))?$/);
    if (!field || found) {
      return new SemvariantError({
        detail: "frontmatter must contain only one guides field",
      });
    }
    found = true;
    block = !field[1];
    if (block) continue;
    const list = field[1]!.match(/^\[(.*)\]$/);
    if (!list) return new SemvariantError({ detail: "guides must be a list" });
    let remaining = list[1]!.trim();
    while (remaining) {
      const entry = remaining.match(
        /^("[^"\\]*"|'[^']*'|[^,"']+)(?:\s*,\s*|$)/,
      );
      if (!entry) return new SemvariantError({ detail: "invalid guides list" });
      const value = parseDirectory(entry[1]!.trim());
      if (value instanceof Error) return value;
      guides.push(value);
      remaining = remaining.slice(entry[0].length);
      if (!remaining && entry[0].trimEnd().endsWith(",")) {
        return new SemvariantError({
          detail: "invalid trailing comma in guides",
        });
      }
    }
  }
  if (!guides.length || new Set(guides).size !== guides.length) {
    return new SemvariantError({
      detail: "guides requires distinct repository directories",
    });
  }
  return guides;
}

function parseDirectory(value: string) {
  const quoted = value.match(/^(?:"([^"\\]*)"|'([^']*)')$/);
  if (quoted) return quoted[1] ?? quoted[2]!;
  if (!value || /[[\]{}"']/.test(value)) {
    return new SemvariantError({ detail: `invalid guides entry: ${value}` });
  }
  return value;
}

function parseRule(filename: string, content: string): Rule | SemvariantError {
  if (!/^R\d{4}\.md$/.test(filename)) {
    return new SemvariantError({
      detail: `${filename}: filename must be RNNNN.md`,
    });
  }
  const frontmatter = content.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);
  if (!frontmatter)
    return new SemvariantError({ detail: `${filename}: missing frontmatter` });
  const guides = parseGuides(frontmatter[1]!);
  if (guides instanceof Error) {
    return new SemvariantError({
      detail: `${filename}: ${guides.message}`,
      cause: guides,
    });
  }
  const body = content.slice(frontmatter[0].length);
  const headings = [...body.matchAll(/^#(?:[ \t]+(.*))?\r?$/gm)];
  if (headings.length !== 1 || !headings[0]?.[1]?.trim()) {
    return new SemvariantError({
      detail: `${filename}: expected exactly one nonempty H1 title`,
    });
  }
  return {
    ruleId: filename.slice(0, -3),
    title: headings[0][1].trim(),
    guides,
    content,
  };
}

function isWithin(root: string, target: string) {
  return target === root || target.startsWith(`${root}${path.sep}`);
}

function assertContained(root: string, target: string) {
  const absolute = path.resolve(root, target);
  if (!isWithin(root, absolute)) {
    return new SemvariantError({
      detail: `path resolves outside repository: ${target}`,
    });
  }
  let ancestor = absolute;
  while (!fs.existsSync(ancestor)) {
    const stat = inspect(ancestor);
    if (stat instanceof Error) return stat;
    if (stat?.isSymbolicLink()) {
      return new SemvariantError({ detail: `dangling symlink: ${ancestor}` });
    }
    ancestor = path.dirname(ancestor);
  }
  const real = filesystem(`Cannot resolve ${ancestor}`, () =>
    fs.realpathSync(ancestor),
  );
  if (real instanceof Error) return real;
  if (!isWithin(root, real)) {
    return new SemvariantError({
      detail: `path resolves outside repository: ${target}`,
    });
  }
}

function validateGuide(root: string, guide: string) {
  const components = guide === "." ? [] : guide.split("/");
  if (
    guide !== "." &&
    (path.isAbsolute(guide) ||
      /^[A-Za-z]:/.test(guide) ||
      guide.includes("\\") ||
      components.some((part) => !part || part === "." || part === ".."))
  ) {
    return new SemvariantError({ detail: `invalid guide directory: ${guide}` });
  }
  let current = root;
  for (const component of components) {
    if (excludedDirectories.has(component)) {
      return new SemvariantError({
        detail: `excluded guide directory: ${guide}`,
      });
    }
    current = path.join(current, component);
    const stat = inspect(current);
    if (stat instanceof Error) return stat;
    if (stat?.isSymbolicLink()) {
      return new SemvariantError({
        detail: `symlink guide directory: ${guide}`,
      });
    }
  }
  const error = assertContained(root, current);
  if (error) return error;
  const stat = inspect(current);
  if (stat instanceof Error) return stat;
  if (!stat?.isDirectory()) {
    return new SemvariantError({
      detail: `guide directory does not exist: ${guide}`,
    });
  }
}

function loadRules(root: string) {
  const directory = path.join(root, rulesDirectory);
  const error = assertContained(root, directory);
  if (error) return error;
  const rules: Rule[] = [];
  if (!fs.existsSync(directory)) return rules;
  const filenames = filesystem(`Cannot list ${directory}`, () =>
    fs.readdirSync(directory),
  );
  if (filenames instanceof Error) return filenames;
  for (const filename of filenames.toSorted()) {
    if (!filename.endsWith(".md") || filename === "AGENTS.md") continue;
    const target = path.join(directory, filename);
    const contained = assertContained(root, target);
    if (contained) return contained;
    const stat = filesystem(`Cannot inspect ${target}`, () =>
      fs.statSync(target),
    );
    if (stat instanceof Error) return stat;
    if (!stat.isFile()) {
      return new SemvariantError({ detail: `rule is not a file: ${filename}` });
    }
    const content = read(target);
    if (content instanceof Error) return content;
    const rule = parseRule(filename, content);
    if (rule instanceof Error) return rule;
    for (const guide of rule.guides) {
      const invalid = validateGuide(root, guide);
      if (invalid)
        return new SemvariantError({
          detail: `${rule.ruleId}: ${invalid.message}`,
          cause: invalid,
        });
    }
    rules.push(rule);
  }
  return rules;
}

function renderGuide(target: string, rules: readonly Rule[]) {
  const directory = path.dirname(target);
  return `${[
    generatedMarker,
    `<!-- Edit rules in ${rulesDirectory}/ and run pnpm semvariant generate. -->`,
    "",
    directory === "."
      ? "# Halo repository guidance"
      : `# Guidance for \`${directory}\``,
    "",
    "Semvariant stores repository guidance as scoped rules. This file indexes their titles; full rules contain the rationale, exceptions, and examples.",
    "Rules apply here and in descendant directories, together with rules in ancestor AGENTS.md files.",
    "Before editing or reviewing, run `pnpm semvariant context <paths>` from the repository root. Add `--full` or use `pnpm semvariant show <IDs>` to read the complete guidance before applying it.",
    "Edit the owning rule files, then run `pnpm semvariant generate` and `pnpm semvariant check`. This file is generated; do not edit it by hand.",
    "",
    "## Rules",
    "",
    ...rules.map((rule) => `- ${rule.ruleId}: ${rule.title}`),
  ].join("\n")}\n`;
}

function planGuides(rules: readonly Rule[]) {
  const grouped = new Map<string, Rule[]>();
  for (const rule of rules) {
    for (const guide of rule.guides) {
      const target = guide === "." ? "AGENTS.md" : `${guide}/AGENTS.md`;
      const entries = grouped.get(target);
      if (entries) entries.push(rule);
      else grouped.set(target, [rule]);
    }
  }
  return new Map(
    [...grouped]
      .toSorted(([a], [b]) => a.localeCompare(b))
      .map(([target, entries]) => [target, renderGuide(target, entries)]),
  );
}

function findGuides(directory: string): string[] | SemvariantError {
  const guides: string[] = [];
  const entries = filesystem(`Cannot list ${directory}`, () =>
    fs.readdirSync(directory, { withFileTypes: true }),
  );
  if (entries instanceof Error) return entries;
  for (const entry of entries) {
    if (entry.isSymbolicLink() || excludedDirectories.has(entry.name)) continue;
    const target = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      const nested = findGuides(target);
      if (nested instanceof Error) return nested;
      guides.push(...nested);
    } else if (entry.isFile() && entry.name === "AGENTS.md")
      guides.push(target);
  }
  return guides.toSorted();
}

function compareGuides(
  root: string,
  plan: ReadonlyMap<string, string>,
): GuideDrift | SemvariantError {
  const drift: GuideDrift = {
    missing: [],
    changed: [],
    stale: [],
    collisions: [],
  };
  for (const [target, expected] of plan) {
    const absolute = path.join(root, target);
    const error = assertContained(root, absolute);
    if (error) return error;
    const stat = inspect(absolute);
    if (stat instanceof Error) return stat;
    if (!stat) drift.missing.push(target);
    else if (!stat.isFile() || stat.isSymbolicLink())
      drift.collisions.push(target);
    else {
      const actual = read(absolute);
      if (actual instanceof Error) return actual;
      if (!actual.startsWith(`${generatedMarker}\n`))
        drift.collisions.push(target);
      else if (actual !== expected) drift.changed.push(target);
    }
  }
  const found = findGuides(root);
  if (found instanceof Error) return found;
  for (const absolute of found) {
    const relative = path.relative(root, absolute).split(path.sep).join("/");
    if (plan.has(relative)) continue;
    const content = read(absolute);
    if (content instanceof Error) return content;
    if (content.startsWith(`${generatedMarker}\n`)) {
      drift.stale.push(relative);
    }
  }
  return drift;
}

function describeDrift(drift: GuideDrift) {
  return [
    ...drift.missing.map((target) => `missing: ${target}`),
    ...drift.changed.map((target) => `changed: ${target}`),
    ...drift.stale.map((target) => `stale: ${target}`),
    ...drift.collisions.map(
      (target) => `collision: ${target} (not generator-owned)`,
    ),
  ];
}

function guardGeneratedTarget(root: string, target: string) {
  const valid = validateGuide(root, path.dirname(target));
  if (valid) return valid;
  const absolute = path.join(root, target);
  const stat = inspect(absolute);
  if (stat instanceof Error) return stat;
  if (!stat) return;
  if (stat.isFile() && !stat.isSymbolicLink()) {
    const content = read(absolute);
    if (content instanceof Error) return content;
    if (content.startsWith(`${generatedMarker}\n`)) return;
  }
  return new SemvariantError({
    detail: `Refusing to modify non-generator-owned guide: ${target}`,
  });
}

function generateGuides(
  root: string,
  plan: ReadonlyMap<string, string>,
  drift: GuideDrift,
) {
  if (drift.collisions.length) {
    return new SemvariantError({
      detail: `Refusing to overwrite authored guides:\n${drift.collisions.join("\n")}`,
    });
  }
  const mutations: string[] = [];
  for (const target of [...drift.missing, ...drift.changed].toSorted()) {
    const absolute = path.join(root, target);
    const temporary = `${absolute}.semvariant-${process.pid}`;
    using cleanup = new errore.DisposableStack();
    const guarded = guardGeneratedTarget(root, target);
    if (guarded) return guarded;
    const written = filesystem(`Cannot write ${temporary}`, () =>
      fs.writeFileSync(temporary, plan.get(target)!, { flag: "wx" }),
    );
    if (written instanceof Error) return written;
    cleanup.defer(() => {
      const removed = filesystem(`Cannot clean up ${temporary}`, () =>
        fs.rmSync(temporary, { force: true }),
      );
      if (removed instanceof Error) console.error(removed.message);
    });
    const renamed = filesystem(`Cannot replace ${target}`, () =>
      fs.renameSync(temporary, absolute),
    );
    if (renamed instanceof Error) return renamed;
    mutations.push(
      `${drift.missing.includes(target) ? "created" : "updated"}: ${target}`,
    );
  }
  for (const target of drift.stale) {
    const guarded = guardGeneratedTarget(root, target);
    if (guarded) return guarded;
    const removed = filesystem(`Cannot delete ${target}`, () =>
      fs.rmSync(path.join(root, target)),
    );
    if (removed instanceof Error) return removed;
    mutations.push(`deleted: ${target}`);
  }
  return mutations.join("\n") || "AGENTS.md files are up to date.";
}

function git(root: string, args: readonly string[]) {
  return errore.try({
    try: () =>
      execFileSync("git", [...args], {
        cwd: root,
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
      }),
    catch: (cause) =>
      new SemvariantError({
        detail: `Git failed: git ${args.join(" ")}`,
        cause,
      }),
  });
}

function changedPaths(root: string, args: readonly string[]) {
  if (args.length === 1 && args[0] === "--staged") {
    return gitPaths(root, ["diff", "--name-status", "-z", "--cached", "--"]);
  }
  if (args.length === 2 && args[0] === "--diff") {
    const revision = args[1]!;
    if (!revision || revision.startsWith("-")) {
      return new SemvariantError({
        detail: "revision must not be empty or option-like",
      });
    }
    const commit = git(root, [
      "rev-parse",
      "--verify",
      "--end-of-options",
      `${revision}^{commit}`,
    ]);
    if (commit instanceof Error) return commit;
    const hash = commit.trim();
    if (!/^[0-9a-f]{40,64}$/i.test(hash))
      return new SemvariantError({
        detail: "revision did not resolve to a commit",
      });
    return gitPaths(root, ["diff", "--name-status", "-z", hash, "--"]);
  }
  if (!args.length || args.some((arg) => arg.startsWith("--"))) {
    return new SemvariantError({
      detail: "context requires paths, --staged, or --diff <rev>",
    });
  }
  return args;
}

function gitPaths(root: string, args: readonly string[]) {
  const output = git(root, args);
  if (output instanceof Error) return output;
  const fields = output.split("\0");
  if (fields.at(-1) === "") fields.pop();
  const selected: string[] = [];
  while (fields.length) {
    const status = fields.shift()!;
    if (!/^[A-Z][0-9]*$/.test(status))
      return new SemvariantError({
        detail: `invalid Git name-status field: ${status}`,
      });
    const count = /^[RC]/.test(status) ? 2 : 1;
    if (fields.length < count)
      return new SemvariantError({
        detail: "incomplete Git name-status output",
      });
    selected.push(...fields.splice(0, count));
  }
  return [...new Set(selected)];
}

function context(
  root: string,
  rules: readonly Rule[],
  paths: readonly string[],
  full: boolean,
) {
  const directories = new Set<string>();
  for (const input of paths) {
    const absolute = path.resolve(root, input);
    const error = assertContained(root, absolute);
    if (error) return error;
    const stat = filesystem(`Cannot inspect ${absolute}`, () =>
      fs.statSync(absolute, { throwIfNoEntry: false }),
    );
    if (stat instanceof Error) return stat;
    let directory = stat?.isDirectory() ? absolute : path.dirname(absolute);
    while (true) {
      directories.add(
        path.relative(root, directory).split(path.sep).join("/") || ".",
      );
      if (directory === root) break;
      directory = path.dirname(directory);
    }
  }
  const applicable = rules.filter((rule) =>
    rule.guides.some((guide) => directories.has(guide)),
  );
  const lines = [
    "# Rules context",
    "",
    "## Selected paths",
    ...paths.map((input) => `- ${input}`),
    "",
    "## Applicable rules",
    ...applicable.map((rule) => `- ${rule.ruleId}: ${rule.title}`),
  ];
  if (!applicable.length) lines.push("- None.");
  if (full && applicable.length)
    lines.push(
      "",
      "## Full rules",
      "",
      ...applicable.map((rule) => rule.content.trimEnd()),
    );
  return lines.join("\n");
}

export function runSemvariant(root: string, args: readonly string[]) {
  const rules = loadRules(root);
  if (rules instanceof Error) return rules;
  const plan = planGuides(rules);
  const drift = compareGuides(root, plan);
  if (drift instanceof Error) return drift;
  const [command, ...values] = args;
  const problems = describeDrift(drift);
  if (command !== "generate" && problems.length) {
    return new SemvariantError({
      detail: `Semvariant check failed:\n${problems.join("\n")}\nRun pnpm semvariant generate after fixing collisions.`,
    });
  }
  switch (command) {
    case undefined:
    case "help":
    case "--help":
      return usage;
    case "show": {
      if (!values.length)
        return new SemvariantError({ detail: "show requires IDs" });
      const ids = new Set(values.map((value) => value.toUpperCase()));
      const selected = rules.filter((rule) => ids.has(rule.ruleId));
      return (
        selected.map((rule) => rule.content.trimEnd()).join("\n\n") ||
        "No matching rules."
      );
    }
    case "search": {
      if (!values.length)
        return new SemvariantError({ detail: "search requires queries" });
      const selected = rules.filter((rule) =>
        values.some((value) =>
          rule.content.toLowerCase().includes(value.toLowerCase()),
        ),
      );
      return (
        selected.map((rule) => `${rule.ruleId} — ${rule.title}`).join("\n") ||
        "No matching rules."
      );
    }
    case "context": {
      if (values.filter((value) => value === "--full").length > 1)
        return new SemvariantError({ detail: "duplicate --full flag" });
      const paths = changedPaths(
        root,
        values.filter((value) => value !== "--full"),
      );
      if (paths instanceof Error) return paths;
      return context(root, rules, paths, values.includes("--full"));
    }
    case "check":
      if (values.length)
        return new SemvariantError({ detail: "check accepts no arguments" });
      return "Semvariant rules and AGENTS.md files are valid.";
    case "generate":
      if (values.length)
        return new SemvariantError({ detail: "generate accepts no arguments" });
      return generateGuides(root, plan, drift);
    default:
      return new SemvariantError({
        detail: `unknown command: ${command}\n\n${usage}`,
      });
  }
}
